// @ts-check
import { useJsonFetch } from './useJsonFetch'

/**
 * Load the real corporación-municipal roster scraped from ribarroja.es.
 * Data is generated by `npm run scrape:officials` → public/data/officials.json,
 * which is scraped ⊕ corrected: `officials[]` are the sitting members (`count`
 * and `composition` derive only from them) and `formerOfficials[]` those who
 * left during the mandate, kept with their end date and the acta that records
 * it (see src/scraper/officials-corrections.ts).
 */
export function useOfficials() {
  return useJsonFetch('/data/officials.json')
}

/**
 * One lookup for every page that resolves a slug — the detail view, the cards
 * and Cmd+K. A former member is still a person the site can render, so the
 * lookup spans both arrays and SAYS which one it hit: `former` is the row
 * itself when the person left, null when they sit today. Nothing downstream
 * has to filter the roster by hand, which is how a former member would fall
 * out of one surface and not another.
 *
 * @param {{ officials?: any[], formerOfficials?: any[] } | null | undefined} snap
 * @param {string} slug
 * @returns {{ official: any | null, former: any | null }}
 */
export function findOfficial(snap, slug) {
  const sitting = (snap?.officials ?? []).find((o) => o.slug === slug)
  if (sitting) return { official: sitting, former: null }
  const former = (snap?.formerOfficials ?? []).find((o) => o.slug === slug)
  return former ? { official: former, former } : { official: null, former: null }
}

// Canonical palette lives in lib/party-colors (shared with usePromises'
// PARTY_TONE alias); re-exported here because pages historically import
// partyColor from this hook.
export { PARTY_COLORS, partyColor } from '../lib/party-colors'
